  // Retention
  "excludes.advisoryImmichDb": "Immich хранит альбомы, лица и даты каждой фотографии в базе данных PostgreSQL, а она работает в отдельном контейнере, не в этом, поэтому в эту резервную копию она не попадает. Восстановление отсюда вернёт сами снимки, но без всего этого. BombVault снимает дамп контейнера этой базы данных сам, когда копирует его, так что проверьте, что он есть в вашем расписании.",
  "excludes.advisoryNextcloudDb": "Nextcloud хранит учётные записи, общие ресурсы и теги в базе данных, которая обычно работает в отдельном контейнере, поэтому в эту резервную копию она не попадает. Файлы вернутся, а общий доступ нет. BombVault снимает дамп контейнера этой базы данных сам, когда копирует его, так что проверьте, что он есть в вашем расписании.",
