  "rcloneRemote.heading": "Добавить место назначения SMB или WebDAV",
  "rcloneRemote.hint": "Обращается к общему ресурсу Windows или Samba либо к серверу WebDAV, например Nextcloud, без монтирования на хосте. restic не рекомендует хранить репозиторий на смонтированном общем ресурсе CIFS, а этот способ полностью обходится без монтирования. Пароль передаётся rclone, который сохраняет его в собственном формате, и нигде не хранится открытым текстом. NFS здесь не предлагается, потому что его не поддерживают ни restic, ни rclone: для NFS смонтируйте экспорт в Unraid и укажите на него Путь резервных копий.",
