  "settings.retentionLastInfo": "Хранит N последних резервных копий, независимо от того, когда они были сделаны.",
  "settings.retentionDailyInfo": "Хранит одну резервную копию за каждый из последних N календарных дней с резервной копией — одну в день, а не N копий.",
