  "settings.ownOffsiteRetentionHint": "Источник может хранить копии в своём удалённом репозитории по своим правилам вместо общих правил для удалённых копий выше. Источник без своих правил использует общие.",
  "settings.ownOffsiteRetentionToggleHint": "Вкл.: удалённый репозиторий этого источника хранит копии по пяти правилам ниже, начальные значения берутся из общих правил для удалённых копий. Выкл.: используются общие правила для удалённых копий. Все 0 хранят каждую удалённую копию этого источника.",
  "settings.retentionExtraTargets": "Дополнительные внешние места назначения следуют своим правилам, которые задаются в карточке «Внешняя копия» каждого раздела.",
  "settings.retentionOffsiteScope": "Эти правила действуют для основного внешнего места назначения каждого раздела, то есть адреса в его поле внешней копии. Любое другое внешнее место назначения, в том числе созданное из места назначения, следует своим правилам. Если там одни нули, BombVault никогда его не очищает.",
  "settings.retentionCombineInfo": "Пять правил комбинируются через ИЛИ: резервная копия сохраняется, если её сохранило бы хотя бы одно правило — они не суммируются в фиксированное число. Применяется отдельно к каждой резервируемой записи.",

  // Off-site (rclone)
  "rclone.title": "Внешнее (rclone)",
  "rclone.hint": "Вставьте конфигурацию rclone для резервного копирования в облако (Backblaze B2, S3, Google Drive, …). Хранится в зашифрованном виде. SMB/NFS не требуют rclone: смонтируйте общий ресурс в Unraid и укажите на него Путь резервных копий.",
  "rclone.configured": "Настроенные удалённые хранилища",
  "rclone.pathHint": "Затем установите Путь резервных копий на «rclone:<remote>:<bucket>/path», чтобы отправлять этот раздел off-site.",
  "cloud.title": "Общие облачные учётные данные (S3 / restic REST)",
  "cloud.hint": "Учётные данные для удалённых бэкендов restic, без rclone. После сохранения задайте путь резервной копии на удалённый репозиторий, напр. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo или sftp:user@host:/repo. Секреты хранятся в зашифрованном виде и больше не показываются.",
  "cloud.secretSet": "сохранено — оставьте пустым, чтобы сохранить",
  "cloud.storageClass.label": "Класс хранения off-site",
  "cloud.storageClass.default": "(по умолчанию провайдера)",
  "cloud.storageClass.hint": "Применяется только к нативным бэкендам S3 (репозитории, начинающиеся с s3:). Уровни глубокого архива (Glacier Flexible Retrieval, Deep Archive) намеренно не предлагаются, так как они ломают восстановление restic.",
  "cloud.credSets.title": "Дополнительные наборы учётных данных",
  "cloud.credSets.hint": "Задайте одному или нескольким внешним местам назначения собственные учётные данные S3 или restic REST вместо общих указанных выше.",
  "cloud.credSets.add": "Добавить набор учётных данных",
  "cloud.credSets.name": "Имя",
  "cloud.credSets.none": "Дополнительных наборов учётных данных пока нет.",
  "cloud.credSets.kept": "{name} (сохранённые учётные данные)",
  "export.encrypt.hint": "Репозитории restic уже зашифрованы. Это опционально шифрует обычные артефакты экспорта (tar.gz контейнера и ВМ вместе с их xml, и flash-zip) с помощью age, чтобы их можно было безопасно хранить или перемещать за пределы сервера.",
  "export.encrypt.ageInfo": "age (age-encryption.org) — небольшой современный инструмент шифрования файлов, более простая альтернатива GPG для шифрования файла для одного или нескольких получателей.",
  "export.encrypt.enable": "Шифровать экспорты с помощью age",
  "export.encrypt.enableHint": "Когда включено, экспорты контейнеров, ВМ и flash запечатываются age перед записью на диск и получают суффикс .age.",
  "export.encrypt.kitSealed": "Набор для восстановления тоже запечатывается и сохраняется как bombvault-recovery-kit.md.age. Он остаётся читаемым текстом (ASCII armor), поэтому его по-прежнему можно вставить в менеджер паролей или распечатать, но чтобы открыть его, понадобится ваш закрытый ключ age: храните этот ключ там, где он не зависит от самого набора.",
  "export.encrypt.recipients": "Получатели age",
  "export.encrypt.recipientsHint": "По одному получателю в строке. Используйте публичный ключ age (age1...) или публичный ключ SSH. Для расшифровки вне сервера нужен соответствующий закрытый ключ. Если шифрование включено, но нет действительного получателя, экспорт завершается ошибкой вместо записи открытого текста.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Добавьте хотя бы одного получателя age, иначе зашифрованный экспорт завершится ошибкой.",
  "rclone.save": "Сохранить конфигурацию",

