  "runReason.stalledReading": "one=остановлено сторожем зависаний после {n} часа без прогресса во время чтения {dataset}|few=остановлено сторожем зависаний после {n} часов без прогресса во время чтения {dataset}|many=остановлено сторожем зависаний после {n} часов без прогресса во время чтения {dataset}|other=остановлено сторожем зависаний после {n} часа без прогресса во время чтения {dataset}",
