  "settings.compressionInfo": "Как restic упаковывает новые данные в этот репозиторий. Автоматически — значение restic по умолчанию, подходит для большинства данных. Максимально экономит больше места и требует больше процессорного времени при резервном копировании и копировании. Выкл. хранит данные без сжатия, что полезно для уже сжатых данных, например видео или фото. Репозиторий в старом формате версии 1 не умеет сжимать и игнорирует эту настройку.",
