  "offsite.wizard.passwordWarning": "Этот пароль показывается один раз и никогда не сохраняется BombVault. Сохраните его сейчас — он нужен для учётных данных ниже и не может быть восстановлен.",
  "offsite.wizard.tlsNote": "Этот рецепт использует обычный HTTP — в доверенной сети LAN или VPN это не проблема. Если сервер хранения доступен через интернет, разместите rest-server за HTTPS (обратный прокси с TLS), чтобы учётные данные репозитория не передавались в открытом виде.",
  "offsite.wizard.password": "Сгенерированный пароль (сохраните)",
  "offsite.wizard.passwordInfo": "Один секрет в двух видах. Открытый текст выше идёт в REST-пароль этого места назначения, здесь на этой машине. Рецепты ниже несут тот же пароль уже хешированным, в строке, дописывающей в .htpasswd, и эта строка идёт на машину хранения. Хешировать вам ничего не нужно.",
  "offsite.wizard.repoUrlInfo": "Первая часть пути — это пользователь, а не папка: rest:http://mashina:8000/polzovatel/repozitoriy. Созданный сервер отдаёт каждому пользователю только его путь, поэтому пропущенный пользователь отвечает 401 даже с верным паролем.",
  "offsite.wizard.step3": "3 · URL репозитория + учётные данные",
