  "offsite.wizard.repoUrlPlaceholder": "rest:http://192.168.x.x:8000/bombvault-containers/containers",
  "offsite.wizard.repoUserMismatch": "Адрес начинается с «{segment}», а эти учётные данные входят как «{user}». С --private-repos оба должны быть одним и тем же словом, иначе сервер отвечает 401.",
  "offsite.wizard.credentials": "Учётные данные",
  "offsite.wizard.credsSharedElsewhere": "Использует общие облачные учётные данные. Выберите набор, чтобы у этого места назначения были собственные.",
  "offsite.wizard.credsInSet": "Это место назначения использует набор «{name}». Данные управляются там.",
  "offsite.wizard.credLoadError": "Не удалось загрузить существующие учётные данные — перезагрузите перед редактированием.",
  "offsite.wizard.step4": "4 · Включите защиту append-only",
  "offsite.immutable": "Неизменяемый (append-only)",
  "offsite.immutableHint": "BombVault перестаёт очищать/удалять на внешней стороне и передаёт управление хранением удалённой стороне. Удалённая сторона должна действительно отклонять удаления — проверяется ниже.",
  "offsite.rcloneWarning": "rclone serve restic --append-only имеет открытый баг повторных попыток в upstream, из-за которого могут теряться операции добавления. Для неизменяемого внешнего места назначения рекомендуется rest-server.",
  "offsite.s3Unverified": "Примечание: append-only для S3 нельзя проверить автоматически. Настройте версионирование бакета + запрет на удаление вручную; в карте оценки этот раздел остаётся отмеченным как непроверенный.",
  "dest.title": "Места назначения",
