  "dest.group.fromGroup": "Из вашей группы",
  "dest.groupTip.fromGroup": "Принимающие серверы, которые экземпляры вашей группы запускают в режиме append-only. Если выбрать один, подставляются его адрес и отдельный логин этого экземпляра. Затем проверьте соединение, как и для любого места назначения.",
  "dest.receiver.needsAddress": "нужен прямой адрес",
  "dest.receiver.needsAddressTip": "Этот экземпляр достаёт до другого только через relay, а relay не переносит резервные копии. Добавьте адрес того экземпляра в разделе Настройки, Сопряжение.",
  "dest.group.cloud": "Облачное хранилище",
