  "dest.fit.slower": "работает, но медленнее",
  "dest.groupTip.storage": "Бакеты с доступом по ключу. Быстро, недорого за терабайт, а с Object Lock старые версии сохраняются, даже если кто-то их удалит.",
  "dest.groupTip.selfs3": "S3-сервер на вашем собственном оборудовании, например второй сервер Unraid у родственников.",
