  "dest.groupTip.cloud": "Сервисы для документов и фотографий. Они ограничивают число запросов, поэтому первая резервная копия и очистка занимают больше времени.",
  "dest.note.slower": "Работает, но медленнее. {name} ограничивает число запросов, поэтому первая резервная копия и очистка здесь занимают гораздо больше времени, чем в сервисе хранения.",
  "dest.note.dailyCap": "Google Drive принимает не более 750 ГБ загрузок в сутки.",
