  "dest.token.run": "Выполните это на компьютере с браузером и войдите в аккаунт",
  "dest.token.tip": "BombVault работает на сервере без браузера. rclone открывает вход на вашем компьютере, а затем выводит токен, который нужно вставить в поле ниже. rclone для Windows, macOS и Linux есть на rclone.org.",
  "dest.sshKey": "Добавьте публичный ключ SSH BombVault на сервер",
  "dest.sshKey.tip": "Тот же ключ, который BombVault использует для резервных копий ВМ по SSH. С этим ключом пароль не нужен, а вход по паролю на сервере можно отключить.",
