  "offsite.prune.title": "5 · Удалённая очистка",
  "offsite.prune.info": "Этот шаг лишь сообщает, что происходит, он ничего не настраивает. Будет ли эта копия очищаться, определяют append-only из шага 4 и значения хранения в разделе Настройки, Места назначения. Чтобы всё же очистить append-only-копию, выполните restic forget --prune на стороне места назначения — либо по собственному расписанию, либо ненадолго подняв второй REST-сервер без append-only, очистив через него и снова выключив его.",
  "offsite.prune.stateFarSide": "Отсюда эту копию ничего не очищает. Append-only включён, поэтому BombVault только добавляет в неё, а очистка — дело стороны места назначения.",
