  "offsite.prune.effective": "Хранит {last} последних, {daily} ежедневных, {weekly} еженедельных, {monthly} ежемесячных, {yearly} ежегодных.",
  "offsite.prune.editedElsewhere": "Задаётся в разделе Настройки, Места назначения. Все источники используют эти значения, если у источника нет своих правил.",
  "offsite.prune.budgetInfo": "Поднимает тревогу, как только удалённый репозиторий перерастёт указанное число гигабайт. Он никогда ничего не удаляет, так что это страховка для копии, которую ничего не очищает.",
  "settings.retentionImmutableNotPruned": "Внешнее место назначения с append-only никогда не очищается отсюда, что бы ни говорили эти значения. Отдельный шаг в удалённом мастере объясняет, как очистить его со стороны места назначения.",

