  "zfs.children": "Наборы данных в этой записи",
  "zfs.childrenHint": "Эта запись сохраняет набор данных и все наборы под ним из одного снимка. Новые дочерние наборы добавляются сами. Выключите один, чтобы оставить его в стороне вместе со всем, что под ним. Наборы, которые нельзя прочитать, пропускаются и перечисляются при каждом запуске.",
  "zfs.excludedGone": "Оставлено в стороне, на сервере больше нет",
  "zfs.excludes": "Шаблоны исключений",
  "zfs.excludesHint": "По одному шаблону в строке. Шаблон, начинающийся с /, отсчитывается от набора данных этой записи, а дочерний набор — это папка со своим именем, например /plex/Library/Cache. Шаблон без / в начале совпадает на любой глубине в каждом наборе, например *.tmp или Library/Cache. Это отличается от раздела «Папки», где / означает корень контейнера.",
  "zfs.excludesCount": "one={n} шаблон исключения|few={n} шаблона исключения|many={n} шаблонов исключения|other={n} шаблона исключения",
  "zfs.excludeMatches": "one=совпадает с {n} записью|few=совпадает с {n} записями|many=совпадает с {n} записями|other=совпадает с {n} записи",
