  "zfs.safety.row": "{dataset}, {age}, {size}",
  "zfs.safety.old": "Самому старому страховочному снимку больше 30 дней. Он держит в пуле удалённые и изменённые данные, пока вы его не удалите.",
  "zfs.safety.hint": "BombVault сделал эти снимки прямо перед восстановлением в набор данных, чтобы состояние до восстановления можно было вернуть. BombVault никогда не удаляет их сам. Отдельные файлы вернёте, скопировав их из .zfs/snapshot/<name> внутри набора данных. zfs rollback работает, только пока это самый новый снимок этого набора; zfs rollback -r удаляет все более новые снимки, в том числе автоматические.",
  "zfs.safety.deleteConfirm": "Удалить страховочный снимок {name} набора {dataset}? Состояние до того восстановления вернуть уже не получится.",
