  // Restore from another BombVault repo — Recovery page (#61 task 11)
  "recovery.abTitle": "Импорт из плагина Appdata.Backup",
  "recovery.abIntro": "Превращает архивы, записанные плагином Appdata.Backup, в точки восстановления соответствующих контейнеров, каждую с датой, когда плагин её создал. Архивы только читаются, никогда не изменяются и не удаляются. Каждый распаковывается рядом с репозиторием, сохраняется в резервную копию, а распакованная копия снова удаляется, поэтому там нужно место для самого большого архива.",
  "recovery.abFolder": "Папка резервных копий плагина",
