  "recovery.foreignCredsIntro": "Похоже, это удалённый репозиторий, поэтому нужны учётные данные бэкенда другого сервера. Они используются только в этом сеансе и никогда не сохраняются. Ваши собственные внешние учётные данные здесь намеренно не используются повторно: они были бы отправлены на адрес, который вы только что ввели.",
