  "recovery.foreignDbDumps": "one=В этом репозитории {n} дамп базы данных. Достаньте его через командную строку restic, как описано в аварийном наборе.|few=В этом репозитории {n} дампа баз данных. Достаньте один через командную строку restic, как описано в аварийном наборе.|many=В этом репозитории {n} дампов баз данных. Достаньте один через командную строку restic, как описано в аварийном наборе.|other=В этом репозитории {n} дампа баз данных. Достаньте один через командную строку restic, как описано в аварийном наборе.",
  "recovery.dumpOnlyTitle": "Базы данных, сохранённые только дампом",
