  "recovery.foreignLatest": "Последняя копия",
  "recovery.foreignTargetFolder": "Целевая папка",
  "recovery.foreignWholeSet": "Весь набор",
  "recovery.foreignPickSubfolder": "Выбрать подпапку",
  "recovery.foreignSubfolderHint": "Восстанавливает в целевую папку только отмеченные подпапки или файлы этого набора — например, один стек из полной резервной копии appdata.",
