  "mcp.hint": "Позволяет ИИ-ассистентам вроде Claude читать состояние резервных копий этого сервера, запускать копирование и отменять то, что они сами запустили, через Model Context Protocol. Восстановление, удаление и настройки остаются в этом веб-интерфейсе.",
