  "mcp.statusNoneWorks": "Выключено: ни один ключ не работает",
  "mcp.noPasswordWarning": "Пароль для входа не задан, поэтому этот веб-интерфейс открыт всем в вашей сети, и кто может его открыть, может и создать ключ.",
  "mcp.setPassword": "Задать пароль для входа",
  "mcp.needsPasswordForHost": "Эта страница открыта как {host}. Без пароля для входа ключи можно создавать и заменять только с IP-адреса или локального имени вроде tower или tower.local, чтобы ни одна страница в интернете не смогла создать ключ. Пароль для входа снимает это ограничение для данного адреса. BombVault можно открыть и по локальному адресу.",
  "mcp.restoreRevokedNotice": "Восстановление конфигурации отозвало все ключи MCP. Создайте новые ключи для своих ассистентов.",
  "mcp.appKeyChanged": "APP_KEY изменился после создания этих ключей, поэтому они больше не работают. Замените каждый ключ и обновите своих ассистентов.",
