  "mcp.endpointLabel": "Точка подключения",
  "mcp.endpointHint": "Адрес, к которому подключается ваш ассистент. Он говорит на Streamable HTTP и ждёт ключ в заголовке Authorization или X-API-Key либо токен доступа, когда ассистент вошёл через OAuth.",
  "mcp.newKey": "Новый ключ",
