  "mcp.allowStart": "Разрешить запуск копирования",
  "mcp.allowStartHint": "С этой настройкой ассистент может запустить копирование одной записи, целого раздела или полный бэкап и отменить то, что запустил сам: не больше {n} в час, с промежутком {minutes} минут для одной записи и {perDay} на запись в сутки. Копирование останавливает работающие контейнеры, пока не закончится. Без неё ключ может только читать.",
  "mcp.createKey": "Создать ключ",
  "mcp.created": "Ключ создан",
  "mcp.labelInvalid": "Дайте ключу название не длиннее 64 символов.",
