  "mcp.limitReached": "one=Уже есть {n} активный ключ. Отзовите его, прежде чем создавать новый.|few=Уже есть {n} активных ключа. Отзовите один, прежде чем создавать новый.|many=Уже есть {n} активных ключей. Отзовите один, прежде чем создавать новый.|other=Уже есть {n} активных ключей. Отзовите один, прежде чем создавать новый.",
  "mcp.newKeyTitle": "Ваш новый ключ",
  "mcp.showOnce": "Скопируйте его сейчас. BombVault хранит только отпечаток и показать ключ снова не сможет.",
  "mcp.copyKey": "Скопировать ключ",
  "mcp.dismissKey": "Я его скопировал",
  "mcp.snippetsLabel": "Подключить клиент",
  "mcp.chooseClient": "Выбрать клиент",
  "mcp.search": "Поиск клиентов",
  "mcp.noMatch": "Подходящего клиента нет. Любой другой клиент подключается через «Другой клиент».",
  "mcp.connectHint": "Выберите свой клиент, и получите настройку, сделанную под него: ключ с его именем, конфигурацию для копирования и шаг с сертификатом, который ему нужен. Любой другой клиент подключается через «Другой клиент». То, что читает ассистент, например названия записей, историю и сообщения об ошибках, уходит стоящему за ним поставщику ИИ, после того как BombVault уберёт пути хоста, расположения репозиториев и учётные данные.",
  "mcp.groupLocal": "На этом компьютере",
  "mcp.groupCloud": "В облаке",
  "mcp.cloudWarningTitle": "BombVault должен быть доступен из интернета",
  "mcp.cloudWarning": "Эти сервисы обращаются к BombVault с серверов своего поставщика, а не с вашего компьютера. Тогда BombVault должен быть доступен из интернета с публично доверенным сертификатом, например за обратным прокси. Вход на этом прокси может защищать веб-интерфейс, но /mcp должен проходить до BombVault, который сам проверяет ключ: эти сервисы не умеют входить на прокси. Le Chat отклоняет самоподписанные сертификаты.",
  "mcp.otherClient": "Другой клиент",
