  "mcp.pickHint": "BombVault показал каждый ключ один раз, при создании. Если его у вас больше нет, создайте новый.",
  "mcp.pickShared": "Шаг 3 станет зелёным при следующем вызове с этим ключом, какой бы клиент его ни сделал. Чтобы точно знать, что это этот клиент, дайте каждому клиенту свой ключ, как делает Новый ключ.",
  "mcp.stepConfig": "Добавить BombVault в {name}",
