  "mcp.oauthToggle": "Вход через OAuth",
  "mcp.oauthHint": "Для ChatGPT, Claude на claude.ai и других сервисов, которые не принимают ключ. Они отправляют вас на страницу BombVault, где вы входите со своим паролем для входа и разрешаете им доступ. Они обращаются к BombVault со своих серверов, поэтому BombVault должен быть доступен из интернета по публичному адресу ниже, с сертификатом, которому доверяют браузеры. Если его выключить, все клиенты выйдут из системы.",
