  "settings.catchUpMissedHint": "Если сервер был выключен, когда расписание должно было сработать, эта резервная копия запустится примерно через две минуты после старта BombVault.",
  "settings.watchdogHint": "Раз в день проверяет, не просрочена ли какая-либо включённая резервная копия (старше удвоенного интервала её расписания), и отправляет одно уведомление на инцидент через настроенные выше каналы.",
  "settings.watchdogToggle": "Сообщать о просроченных копиях",
  "settings.coresLabel": "Потоки ЦП (0 = все)",
  "settings.coresHint": "Сколько потоков ЦП может использовать резервное копирование. 0 означает все ядра. Число ограничивает то, сколько работы идёт одновременно, а не сколько потоков показывает top или btop: restic всегда держит их больше лимита, и большинство ждёт диск, а не занимает ядро.",
  "settings.cacheHint": "Движок резервного копирования хранит в /config кэш данных репозитория, чтобы инкрементальные и внешние запуски оставались быстрыми. Когда кэш превышает этот предел, после запланированных запусков удаляются наиболее давно использованные кэши репозиториев.",
  "settings.cacheLimitLabel": "Предел размера кэша (МБ, 0 = без ограничений)",
