  "instances.role.waiting": "Запрос отправлен",
  "instances.role.diff": "С приёмником этот сервер отправляет: после каждой резервной копии он сам кладёт свою внешнюю копию на другой экземпляр, а тот не даёт ничего удалять. С подтягивающим другой экземпляр забирает: он читает резервные копии этого сервера по своему расписанию, а этот сервер не знает ни его место назначения, ни его учётные данные. Сервер ZFS принимает реплики ZFS, то есть точные поблочные копии датасетов, а не резервные копии.",
  "instances.role.receiverTip": "Хранит внешние копии этого сервера в rest-server в режиме append-only. Этот сервер не может ничего удалить там, даже если им завладеет посторонний.",
  "instances.role.fetcherTip": "Забирает резервные копии этого сервера по своему расписанию. Этому серверу для этого не нужно быть включённым.",
  "instances.role.zfsTip": "Принимает реплики ZFS этого сервера. Какая запись ZFS реплицируется туда, выбирается в её настройках в разделе Реплика.",
