  "instances.role.keeperTip": "Хранит запечатанную копию набора для восстановления этого сервера и не может её открыть. Если этот сервер будет потерян, новая установка в вашей группе заберёт копию оттуда и откроет её вашим кодом выдачи.",
  "instances.role.offKeeper": "Этот сервер просит экземпляр {peer} удалить депозит.",
  "keeper.offLast": "Экземпляр {peer} единственный хранитель. Когда хранителей не останется, этот сервер сбросит код выдачи, и следующий депозит получит новый код.",
  "keeper.notTold": "Экземпляр {peer} был недоступен и всё ещё хранит депозит. Удалите его там в разделе «Экземпляры», «Депозит ключа».",
  "keeper.lead": "Экземпляр {peer} получает запечатанную копию набора для восстановления этого сервера и не может её открыть. Если этот сервер когда-нибудь будет потерян, новая установка, которая присоединится к вашей группе, сможет запросить копию у экземпляра {peer}.",
  "keeper.need.title": "В тот день вам понадобятся три вещи",
  "keeper.need.words": "Двенадцать слов вашей группы",
