  "keeper.code.tip": "Двадцать букв и цифр в четырёх группах по пять. Этот сервер хранит то, что нужно, чтобы запечатать депозит под код, но не сам код.",
  "keeper.code.lead": "Запишите этот код сейчас. Он открывает депозит ключа. Он показывается только один раз, и этот сервер его не хранит.",
  "keeper.code.lost": "Если вы потеряете код, вы сможете создать здесь новый, пока работает этот сервер. Новый код заменит этот.",
