  "apps.phone.title": "Приложение для Android",
  "apps.phone.hint": "BombVault для телефонов на Android. Показывает все серверы вашей группы, собирает их активность в одном журнале и сопрягается по двенадцати словам.",
  "apps.phone.qrCode": "QR-код",
