  "apps.parleyport.title": "ParleyPort",
  "apps.parleyport.hint": "Ваш собственный Relay для BombVault и KnightLoader. Экземпляры в разных сетях встречаются там, когда ни один не может достучаться до другого, и он передаёт дальше то, что сам прочитать не может. Он нужен вам, только если вы предпочитаете не пользоваться Relay проекта и ни один из ваших экземпляров не доступен снаружи.",
