  "relay.serveClients": "one={n} экземпляр подключён прямо сейчас|few={n} экземпляра подключено прямо сейчас|many={n} экземпляров подключено прямо сейчас|other={n} экземпляра подключено прямо сейчас",
  "relay.instanceCert": "Тогда Relay работает по адресу /relay/connect на его адресе, за тем же самым обратным прокси и сертификатом.",
  "relay.instanceCertTip": "Ему не нужен собственный сертификат. Того, что уже делает ваш экземпляр доступным извне, достаточно и для Relay.",
  "relay.addressLabel": "Адрес вашего Relay",
  "relay.addressTip": "Этот адрес применяется только к этому экземпляру. Введите его на каждом экземпляре, который должен быть доступен через ваш Relay.",
  "relay.plaintextWarning": "У этого адреса нет TLS, поэтому ключ Relay проходит по сети открытым текстом. Любой на пути может прочитать его и присоединиться к вашей группе на Relay. Он не сможет прочитать, что ваши экземпляры отправляют друг другу, но увидит, какие экземпляры и когда общаются. Используйте это только в сети, которой доверяете.",
