  "receiver.checkFailedHelp":
    "BombVault только читает полученный репозиторий и не станет чинить его за вас. Чтобы починить самостоятельно, запустите restic по указанному выше пути с паролем, выведенным из APP_KEY отправляющего экземпляра: он лежит в наборе восстановления того экземпляра, а не этой машины. Сначала попробуйте `restic repair index`, затем `restic repair snapshots`, если снимки по-прежнему не читаются.",
