  "receiver.server.title": "Принимающий сервер",
  "receiver.server.tip": "Сервер rest-server в режиме append-only на этом устройстве. Остальные экземпляры вашей группы могут копировать на него свои внешние копии, а удалить уже поступившее не сможет даже тот, у кого есть их логин.",
  "receiver.server.intro": "Позвольте партнёрам копировать свои внешние копии на это устройство. BombVault запускает здесь rest-server в режиме append-only и предлагает его экземплярам вашей группы.",
  "receiver.server.setUp": "Настроить принимающий сервер",
