  "anomaly.title": "Аномалии",
  "anomaly.cardHint": "BombVault сравнивает каждую резервную копию записи с предыдущими и называет то, что выбивается: намного больше новых данных, чем обычно, перезапись большей части данных, источник, который сильно уменьшился или вырос, уменьшившийся дамп базы данных, копию, которая вдруг идёт намного дольше, повторяющиеся сбои, проверку восстановления, которая перестала проходить, и диск, который скоро заполнится. Большинству проверок сначала нужны 10 копий записи. Запись ZFS проверяется по наборам данных, поэтому опустевший дочерний набор данных заметен даже в большом дереве.",
