  "anomaly.prunePaused": "Очистка выполнена. Старые копии записей с открытой аномалией сохранены: {names}",
  "anomaly.settings.title": "Аномалии",
  "anomaly.settings.hint": "Сравнивает каждую копию записи с её собственной историей и сообщает о том, что не вписывается. Работает в фоне после каждой копии и ни одну не замедляет. Большинство проверок начинается после 10 копий записи; сбои, перезапись большей части данных и почти пустой источник проверяются с самого начала. Свободное место отслеживается для локальных репозиториев и для репозиториев rclone, которые его сообщают; на пользовательском ресурсе Unraid это свободное место всего массива.",
  "anomaly.settings.toggle": "Обнаруживать аномалии",
  "anomaly.settings.sensitivity": "Чувствительность",
  "anomaly.settings.sensitivityHint": "Строгая сообщает и о небольших изменениях, Мягкая только о крупных, Сбалансированная подходит большинству серверов. Каждой записи можно задать свою настройку в разделе Аномалии, Наблюдение.",
  "anomaly.settings.notifyMin": "Отправлять уведомление для",
  "anomaly.settings.notifyHint": "Использует каналы, настроенные в разделе Уведомления. Каждая запись может изменить это в разделе Аномалии, Наблюдение. Повторяющиеся сбои копий и дампов и неудачные плановые проверки восстановления уже отправляют своё сообщение, поэтому второй раз не отправляются.",
  "anomaly.settings.notifyMuted": "Сейчас ничего не отправляется: уведомления выключены или не настроен ни один канал.",
  "anomaly.settings.openNotifications": "Открыть настройки уведомлений",
  "anomaly.settings.holdToggle": "Сохранять старые копии, если источник резко уменьшился или был перезаписан",
  "anomaly.settings.holdHint": "Три находки приостанавливают удаление старых копий: источник, который внезапно почти пуст, источник, ставший намного меньше, и копия, заново сохранившая большую часть данных, как это выглядит после вымогателя. Иначе хранение удаляло бы хорошие старые копии одну за другой. Пока такая аномалия открыта, сохраняются старые копии только этой записи (или этого дампа базы данных или набора данных ZFS); всё остальное очищается как обычно. Подтвердите аномалию или отметьте её как ожидаемую, чтобы продолжить.",
