  "storage.flow.title": "Места назначения по разделам",
  "storage.flow.hint": "Значение по умолчанию для каждого раздела. На схеме каждая линия является переключателем: щелчок по линии или точке включает или выключает его. Пунктирные линии выключены. В режиме «Переключатели» то же самое настраивается кнопками. Переключатель решает только, куда пойдут новые резервные копии. Записи, которые следуют значению по умолчанию, сразу переходят вместе с ним, поэтому их следующая копия уйдёт в новые места назначения. Уже сохранённые копии остаются там, где лежат, и вы по-прежнему можете восстановить их оттуда. Записи, выбравшие на своей странице собственные места назначения, сохраняют их. Собственные правила раздела, например хранение, сжатие или отдельный адрес, задаются на странице места назначения.",
  "storage.flow.view": "Вид",
